CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), session_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE user_roles (user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN('admin','volunteer')), PRIMARY KEY(user_id,role));
CREATE TABLE sessions (sid TEXT PRIMARY KEY NOT NULL, sess JSON NOT NULL, expired DATETIME NOT NULL);
CREATE INDEX sessions_expired ON sessions(expired);
CREATE TABLE password_reset_tokens (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,used_at TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY,failures INTEGER NOT NULL DEFAULT 0,blocked_until TEXT,updated_at TEXT NOT NULL);
CREATE TABLE organization_settings (id INTEGER PRIMARY KEY CHECK(id=1),organization_name TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',membership_year_end TEXT NOT NULL DEFAULT '03-31',dues_paise INTEGER NOT NULL CHECK(dues_paise>0),opening_cash_paise INTEGER NOT NULL DEFAULT 0 CHECK(opening_cash_paise>=0),demo_mode INTEGER NOT NULL DEFAULT 1 CHECK(demo_mode IN(0,1)),updated_at TEXT NOT NULL);
INSERT INTO organization_settings VALUES(1,'Skyline Student Association','Asia/Kolkata','03-31',150000,0,1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE member_records (id TEXT PRIMARY KEY,user_id TEXT UNIQUE REFERENCES users(id),name TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE,phone TEXT NOT NULL DEFAULT '',student_number TEXT NOT NULL DEFAULT '',archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX member_records_name ON member_records(name);
CREATE TABLE membership_terms (id TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES member_records(id),starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,dues_paise INTEGER NOT NULL CHECK(dues_paise>0),status TEXT NOT NULL DEFAULT 'UNPAID' CHECK(status IN('UNPAID','PAID')),created_at TEXT NOT NULL,CHECK(ends_on>=starts_on),UNIQUE(member_id,starts_on,ends_on));
CREATE INDEX membership_expiry ON membership_terms(member_id,ends_on,status);
CREATE TABLE dues_payments (id TEXT PRIMARY KEY,term_id TEXT NOT NULL UNIQUE REFERENCES membership_terms(id),amount_paise INTEGER NOT NULL CHECK(amount_paise>0),payment_id TEXT UNIQUE REFERENCES payments(id),created_at TEXT NOT NULL);
CREATE TABLE events (id TEXT PRIMARY KEY,title TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'EVENT' CHECK(type IN('EVENT','FUNDRAISER')),description TEXT NOT NULL DEFAULT '',start_at TEXT NOT NULL,end_at TEXT NOT NULL,location TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),seats_sold INTEGER NOT NULL DEFAULT 0 CHECK(seats_sold>=0 AND seats_sold<=capacity),member_price_paise INTEGER NOT NULL DEFAULT 0 CHECK(member_price_paise>=0),nonmember_price_paise INTEGER NOT NULL DEFAULT 0 CHECK(nonmember_price_paise>=0),budget_paise INTEGER NOT NULL DEFAULT 0 CHECK(budget_paise>=0),volunteer_requirement INTEGER NOT NULL DEFAULT 0 CHECK(volunteer_requirement>=0),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PUBLISHED','CANCELLED')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(end_at>=start_at));
CREATE INDEX event_dates ON events(status,start_at,end_at);
CREATE TABLE availability_requests (id TEXT PRIMARY KEY,event_id TEXT NOT NULL UNIQUE REFERENCES events(id),requested_by TEXT NOT NULL REFERENCES users(id),deadline_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE volunteer_availability (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),user_id TEXT NOT NULL REFERENCES users(id),response TEXT NOT NULL CHECK(response IN('AVAILABLE','UNAVAILABLE')),note TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,UNIQUE(event_id,user_id));
CREATE TABLE event_assignments (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),user_id TEXT NOT NULL REFERENCES users(id),role_label TEXT NOT NULL DEFAULT 'Volunteer',can_check_in INTEGER NOT NULL DEFAULT 0 CHECK(can_check_in IN(0,1)),assigned_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(event_id,user_id));
CREATE INDEX assignments_owner ON event_assignments(user_id,event_id);
CREATE TABLE tasks (id TEXT PRIMARY KEY,title TEXT NOT NULL,instructions TEXT NOT NULL DEFAULT '',assignee_id TEXT NOT NULL REFERENCES users(id),event_id TEXT REFERENCES events(id),due_at TEXT,budget_paise INTEGER NOT NULL DEFAULT 0 CHECK(budget_paise>=0),status TEXT NOT NULL DEFAULT 'ASSIGNED' CHECK(status IN('ASSIGNED','IN_PROGRESS','COMPLETED','CANCELLED')),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX task_owner_status ON tasks(assignee_id,status,due_at);
CREATE INDEX task_event ON tasks(event_id,status);
CREATE TABLE tickets (id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),member_id TEXT REFERENCES member_records(id),owner_user_id TEXT REFERENCES users(id),buyer_name TEXT NOT NULL,buyer_email TEXT NOT NULL DEFAULT '',code TEXT NOT NULL UNIQUE,price_paise INTEGER NOT NULL CHECK(price_paise>=0),status TEXT NOT NULL DEFAULT 'VALID' CHECK(status IN('VALID','CANCELLED','USED')),checked_in_at TEXT,checked_in_by TEXT REFERENCES users(id),refund_status TEXT NOT NULL DEFAULT 'NONE' CHECK(refund_status IN('NONE','UNRESOLVED','RESOLVED_MANUALLY')),payment_id TEXT UNIQUE REFERENCES payments(id),created_at TEXT NOT NULL);
CREATE INDEX ticket_event ON tickets(event_id,status);
CREATE TABLE products (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),price_paise INTEGER NOT NULL CHECK(price_paise>=0),member_price_paise INTEGER NOT NULL CHECK(member_price_paise>=0),created_at TEXT NOT NULL);
CREATE TABLE product_variants (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),size TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),UNIQUE(product_id,size));
CREATE TABLE orders (id TEXT PRIMARY KEY,member_id TEXT REFERENCES member_records(id),buyer_name TEXT NOT NULL,total_paise INTEGER NOT NULL CHECK(total_paise>=0),collected INTEGER NOT NULL DEFAULT 0 CHECK(collected IN(0,1)),payment_id TEXT UNIQUE REFERENCES payments(id),created_at TEXT NOT NULL);
CREATE TABLE order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_paise INTEGER NOT NULL CHECK(unit_price_paise>=0));
CREATE INDEX order_item_order ON order_items(order_id);
CREATE TABLE stock_movements (id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL CHECK(quantity<>0),reason TEXT NOT NULL,order_id TEXT REFERENCES orders(id),actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE expense_claims (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),event_id TEXT REFERENCES events(id),task_id TEXT REFERENCES tasks(id),description TEXT NOT NULL,category TEXT NOT NULL,amount_paise INTEGER NOT NULL CHECK(amount_paise>0),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','SUBMITTED','CHANGES_REQUESTED','REJECTED','APPROVED_UNPAID','PAID')),review_note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_at TEXT,approved_at TEXT,paid_at TEXT,payment_id TEXT UNIQUE REFERENCES payments(id));
CREATE INDEX claim_owner_status ON expense_claims(user_id,status,created_at);
CREATE INDEX claim_event ON expense_claims(event_id,status);
CREATE TABLE receipt_files (id TEXT PRIMARY KEY,claim_id TEXT NOT NULL REFERENCES expense_claims(id),stored_name TEXT NOT NULL UNIQUE,original_name TEXT NOT NULL,mime_type TEXT NOT NULL CHECK(mime_type IN('image/jpeg','image/png','application/pdf')),size_bytes INTEGER NOT NULL CHECK(size_bytes>0 AND size_bytes<=5242880),created_at TEXT NOT NULL);
CREATE INDEX receipt_claim ON receipt_files(claim_id);
CREATE TABLE direct_financial_records (id TEXT PRIMARY KEY,direction TEXT NOT NULL CHECK(direction IN('IN','OUT')),amount_paise INTEGER NOT NULL CHECK(amount_paise>0),category TEXT NOT NULL,description TEXT NOT NULL,event_id TEXT REFERENCES events(id),occurred_at TEXT NOT NULL,created_at TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE payments (id TEXT PRIMARY KEY,source_type TEXT NOT NULL CHECK(source_type IN('dues','ticket','order','claim','direct','adjustment')),source_id TEXT NOT NULL,amount_paise INTEGER NOT NULL CHECK(amount_paise>=0),method TEXT NOT NULL CHECK(method IN('cash','upi','card','bank','other')),reference TEXT NOT NULL DEFAULT '',settlement_kind TEXT NOT NULL CHECK(settlement_kind IN('manual','mock')),actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(source_type,source_id));
CREATE TRIGGER payment_source_integrity BEFORE INSERT ON payments BEGIN
 SELECT CASE WHEN NEW.source_type='dues' AND NOT EXISTS(SELECT 1 FROM dues_payments WHERE id=NEW.source_id) THEN RAISE(ABORT,'Invalid dues payment source') END;
 SELECT CASE WHEN NEW.source_type='ticket' AND NOT EXISTS(SELECT 1 FROM tickets WHERE id=NEW.source_id) THEN RAISE(ABORT,'Invalid ticket source') END;
 SELECT CASE WHEN NEW.source_type='order' AND NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.source_id) THEN RAISE(ABORT,'Invalid order source') END;
 SELECT CASE WHEN NEW.source_type='claim' AND NOT EXISTS(SELECT 1 FROM expense_claims WHERE id=NEW.source_id) THEN RAISE(ABORT,'Invalid claim source') END;
 SELECT CASE WHEN NEW.source_type IN('direct','adjustment') AND NOT EXISTS(SELECT 1 FROM direct_financial_records WHERE id=NEW.source_id) THEN RAISE(ABORT,'Invalid direct source') END;
END;
CREATE TABLE ledger_entries (id TEXT PRIMARY KEY,direction TEXT NOT NULL CHECK(direction IN('IN','OUT')),amount_paise INTEGER NOT NULL CHECK(amount_paise>0),category TEXT NOT NULL,description TEXT NOT NULL,event_id TEXT REFERENCES events(id),payment_id TEXT NOT NULL UNIQUE REFERENCES payments(id),claim_id TEXT UNIQUE REFERENCES expense_claims(id),reversal_of TEXT UNIQUE REFERENCES ledger_entries(id),reason TEXT,actor_id TEXT NOT NULL REFERENCES users(id),occurred_at TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(reversal_of IS NULL OR length(trim(reason))>0));
CREATE INDEX ledger_date ON ledger_entries(occurred_at,direction,category);
CREATE INDEX ledger_event ON ledger_entries(event_id,occurred_at);
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger_entries BEGIN SELECT RAISE(ABORT,'Ledger entries are append-only'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT,'Ledger entries are append-only'); END;
CREATE TRIGGER ledger_full_reversal BEFORE INSERT ON ledger_entries WHEN NEW.reversal_of IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM ledger_entries WHERE id=NEW.reversal_of AND amount_paise=NEW.amount_paise AND direction<>NEW.direction AND reversal_of IS NULL) THEN RAISE(ABORT,'Reversal must exactly reverse an original entry') END;
END;
CREATE TABLE announcements (id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,audience TEXT NOT NULL CHECK(audience IN('volunteers','all')),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PUBLISHED','ARCHIVED')),published_at TEXT,created_at TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),announcement_id TEXT NOT NULL REFERENCES announcements(id),read_at TEXT,created_at TEXT NOT NULL,UNIQUE(user_id,announcement_id));
CREATE INDEX notifications_owner ON notifications(user_id,read_at);
CREATE TABLE mock_email_outbox (id TEXT PRIMARY KEY,recipient_email TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'QUEUED' CHECK(status IN('QUEUED','DELIVERED','FAILED')),attempts INTEGER NOT NULL DEFAULT 0,simulate_failure INTEGER NOT NULL DEFAULT 0 CHECK(simulate_failure IN(0,1)),dedupe_key TEXT NOT NULL UNIQUE,error TEXT,created_at TEXT NOT NULL,delivered_at TEXT);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX audit_date ON audit_logs(created_at);
CREATE TABLE idempotency_keys (actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,key TEXT NOT NULL,payload_hash TEXT NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(actor_id,action,key));
